<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &amp;lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">transition-group name=&quot;flip-list&quot; tag=&quot;ul&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&amp;gt;</span></span>
